local s=require("setup.project")local r=require("setup.session")local d=require("setup.server")local i={}i.USAGE="Usage: braincloud-setup [<projectDir>] [--out <path>] [--refresh] [--server <url>] [--no-browser] [--timeout <minutes>]"function i.parse(o)local a={browser=true,timeout=30}local e=1 while o[e]do local t=o[e]if t=="--out"then a.out=o[e+1]e=e+1 elseif t=="--server"then a.server=o[e+1]e=e+1 elseif t=="--refresh"then a.refresh=true elseif t=="--no-browser"then a.browser=false elseif t=="--timeout"then a.timeout=tonumber(o[e+1])or 30 e=e+1 elseif t=="-h"or t=="--help"then a.help=true elseif t:sub(1,1)=="-"then a.bad=t else a.projectDir=t end e=e+1 end return a end function i.openBrowser(e)if love and love.system and love.system.openURL then return love.system.openURL(e)end local t=package.config:sub(1,1)if t=="\\"then return os.execute('start "" "'..e..'"')~=nil end local t=(io.popen("uname"):read("*l")=="Darwin")and"open"or"xdg-open"return os.execute(t.." '"..e.."' >/dev/null 2>&1 &")~=nil end function i.start(o,h,t)t=t or print local n=o.out or s.defaultOutput(o.projectDir or".")local a=r.new(n,{serverUrl=o.server})local e={output=n,session=a}if o.refresh then a:refreshConfig()t("Refreshed "..n)e.finished=true function e.poll()return true end return e end local a=d.new(a,{readAsset=h})a:start()e.server=a e.deadline=os.time()+o.timeout*60 t("brainCloud setup is open at "..a:url())t("Writing config to "..n)if not o.browser or not i.openBrowser(a:url())then t("Open that address in your browser to continue.")end function e.url()return a:url()end function e.poll()if e.finished then return true end local i=a:poll()if i or os.time()>e.deadline then if not i then t("brainCloud setup timed out after "..o.timeout.." minutes.")end a:stop()e.finished=true if s.read(n)then t("Done. In your game:\n  local bc = require(\"braincloud\").new()\n  bc:init()")end end return e.finished end return e end return i
